// @effect-diagnostics nodeBuiltinImport:off -- Content-addressed browser assets generated by Vite.
import { createHash } from "node:crypto";
import { visitStrings, type Parse } from "./contexts.ts";

type AssetEmitter = { emitFile(asset: { type: "asset"; fileName: string; source: string }): string };

export function englishAsset(context: AssetEmitter, name: string, source: string) {
  const hash = createHash("sha256").update(source).digest("hex").slice(0, 16);
  const fileName = "assets/" + name + "-" + hash + ".js";
  context.emitFile({ type: "asset", fileName, source });
  return "/" + fileName;
}

// Chronos-owned copy is already Russian in the source. Only replace authored literals,
// leaving interpolation values, property keys, routing strings and user data intact.
export type EnglishCatalog = {
  exact: Record<string, string>;
  templates: Record<string, string>;
};

export function englishLiterals(code: string, parse: Parse, catalog: EnglishCatalog) {
  if (!/[а-яё]/iu.test(code) && !/\\u0[45]/iu.test(code)) return code;
  const chunks: string[] = [];
  let offset = 0;
  visitStrings(code, parse, (site) => {
    if (site.slots.length) {
      const frame = site.parts.map((part, i) => (i === 0 ? "" : "{" + i + "}") + part).join("");
      const target = catalog.templates[frame];
      if (target === undefined) return;
      // Concatenating separately quoted constants retains the original slot values and evaluation order.
      const fields = target.split(/(\{\d+\})/u);
      const indices = fields.filter((_, i) => i % 2 === 1).map(field => Number(field.slice(1, -1)));
      if (indices.length !== site.slots.length || !indices.every((n, i) => n === i + 1)) return;
      const expression = fields.map((field, i) => i % 2 === 0 ? JSON.stringify(field) :
        "`${" + site.slots[Number(field.slice(1, -1)) - 1] + "}`").join(" + ");
      chunks.push(code.slice(offset, site.start), "(" + expression + ")");
      offset = site.end;
      return true;
    }
    const original = site.parts[0]!;
    const key = original.trim().replace(/\s+/gu, " ");
    if (!Object.hasOwn(catalog.exact, key)) return;
    const value = original.replace(original.trim(), () => catalog.exact[key]!);
    chunks.push(code.slice(offset, site.start), JSON.stringify(value));
    offset = site.end;
    return true;
  });
  return chunks.length ? chunks.join("") + code.slice(offset) : code;
}

export function localizeEntryHtml(html: string, englishSetup: string, supportedLocales: readonly string[]) {
  const links: string[] = [];
  const withoutPreloads = html.replace(/<link\b[^>]*\brel="modulepreload"[^>]*>/gu, tag => {
    const href = /\bhref="([^"]+)"/u.exec(tag)?.[1];
    if (!href) return tag;
    links.push(href);
    return "";
  });
  const entryTag = /<script\b(?=[^>]*\btype="module")[^>]*\bsrc="([^"]+)"[^>]*><\/script>/u;
  if (!entryTag.test(withoutPreloads)) throw new Error("Missing Chronos HTML module entry");
  return withoutPreloads.replace(entryTag, (_tag, entry: string) => {
    // The desktop settings read is shared with hydration. An import map has to be in
    // place before even the first modulepreload (which can resolve transitive imports).
    return '<script type="module">\n' +
      'let saved;\n' +
      'try { if (window.desktopBridge) {\n' +
      '  window.__chronosInitialSettings = window.desktopBridge.getClientSettings();\n' +
      '  saved = await window.__chronosInitialSettings;\n' +
      '} else saved = JSON.parse(localStorage.getItem("t3code:client-settings:v1")); } catch {}\n' +
      'const language = saved?.language || "ru";\n' +
      'window.__chronosInitialLanguage = language;\n' +
      // Keep explicit choices on the fast path. For System use the same catalog order,
      // regional matching and English fallback as T3 when resolving navigator.languages.
      'const selectShell = language => {\n' +
      '  if (language === "ru" || language === "en") return language;\n' +
      '  const supported = ' + JSON.stringify(supportedLocales.map(locale => locale.toLowerCase())) + ';\n' +
      '  if (supported.includes(language.toLowerCase())) return "ru";\n' +
      '  for (const tag of navigator.languages) {\n' +
      '    const normalized = tag.trim().toLowerCase(), base = normalized.split(/[-_]/)[0];\n' +
      '    if (supported.includes(normalized) || (!/^zh[-_](hant|tw|hk|mo)\\b/.test(normalized) && supported.includes(base))) return base === "en" ? "en" : "ru";\n' +
      '  } return "en";\n};\n' +
      'window.__chronosSelectShell = selectShell;\n' +
      'const shell = selectShell(language); window.__chronosShellLanguage = shell;\n' +
      'document.documentElement.lang = shell;\n' +
      'const imports = shell === "en" ? (await import(' + JSON.stringify(englishSetup) + ')).imports : {};\n' +
      'for (const href of ' + JSON.stringify(links) + ') {\n' +
      '  const link = document.createElement("link"); link.rel = "modulepreload";\n' +
      '  link.crossOrigin = ""; link.href = imports[href] || href; document.head.append(link);\n' +
      '}\nawait import(' + JSON.stringify(entry) + ');\n</script>';
  });
}
